/* ============================================================
   БЛОК: LOCATION — расположение проекта (карта, метки, ссылки).
   Зависимости: page.css (.detail-section, .section-copy;
   отступ .location-section.detail-section-pad задан там же).
   Карту и ссылки подставляет page.js.
   ============================================================ */

.location-visual {
  position: relative;
  min-height: clamp(360px, 56vw, 690px);
  border-radius: 28px;
  background:
    linear-gradient(180deg, rgba(13, 15, 18, .08), rgba(13, 15, 18, .38)),
    url("https://images.unsplash.com/photo-1534471812555-5b0bb08f034c?auto=format&fit=crop&w=1800&q=84") center / cover no-repeat;
  overflow: hidden;
}

body[data-project="ozmakon-business"] .location-visual {
  min-height: clamp(340px, 46vw, 620px);
  border: 1px solid rgba(21, 24, 29, .08);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .24);
}

.map-label.accent {
  background: #15181d;
  color: #fff;
}

.location-actions a {
  min-height: 48px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 18px;
  border: 1px solid rgba(21, 24, 29, .12);
  border-radius: 13px;
  background: #fff;
  color: #15181d;
  font-weight: 900;
}

@media (max-width: 980px) {
  .location-actions {
    justify-content: flex-start;
    flex-wrap: wrap;
  }
}

@media (max-width: 560px) {
  .location-grid {
    grid-template-columns: 1fr;
  }

  .location-visual {
    min-height: 360px;
    border-radius: 22px;
  }

  .location-actions a {
    width: 100%;
    justify-content: center;
  }
}
/* ==== project-map v2 ==== */
/* Карта проекта вместо фото-заглушки с метками в процентах.
   Рантайм — backend/src/services/runtime/map-runtime.js, данные — estate:
   mapHouse (есть ли карта), mapPoints, mapLegend, mapOffices. Правила ниже
   перекрывают старые правила блока выше. */

.location-visual {
  background: #ece7dc;
}

/* У проекта нет ни точки дома, ни картинки карты — пустую рамку не показываем. */
.location-visual:not(:has(.location-map-image, [data-map])) {
  display: none;
}

.project-map {
  position: absolute;
  inset: 0;
}

/* Специфичнее .maplibregl-map из CSS MapLibre: та ставит position: relative,
   и холст без своей высоты схлопнулся бы. */
.project-map .project-map-canvas {
  position: absolute;
  inset: 0;
}

.project-map[data-map-state="failed"] .project-map-canvas {
  display: none;
}

/* --- Легенда: фильтр по типам мест --- */

.project-map-legend {
  position: absolute;
  z-index: 2;
  top: 16px;
  left: 16px;
  right: 64px;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  /* Сквозь промежутки между кнопками карту можно тащить. */
  pointer-events: none;
}

.project-map-legend:empty {
  display: none;
}

.project-map-filter {
  pointer-events: auto;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 36px;
  padding: 0 12px 0 5px;
  border: 0;
  border-radius: 999px;
  background: rgba(255, 255, 255, .94);
  color: #15181d;
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  line-height: 1;
  box-shadow: 0 6px 18px rgba(13, 15, 18, .14);
  cursor: pointer;
  transition: opacity .2s ease, box-shadow .2s ease;
}

.project-map-filter[aria-pressed="false"] {
  opacity: .5;
  box-shadow: none;
}

.project-map-filter-icon,
.project-map-pin-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.project-map-filter-icon {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: var(--map-color, #15181d);
  color: #fff;
}

.project-map-filter-icon svg {
  width: 15px;
  height: 15px;
}

.project-map-filter-count {
  color: rgba(21, 24, 29, .45);
}

/* --- Метки. Внешний элемент метки двигает MapLibre, оформление — внутри. --- */

/* Слои: места, над ними дом, выше всех — отдел продаж (он главнее);
   открытая подсказка места — поверх всего (z-index 4 ставит рантайм). */
.project-map-marker--house {
  z-index: 2;
}

.project-map-marker--office {
  z-index: 3;
}

.project-map-marker--house .project-map-pin,
.project-map-marker--office .project-map-pin {
  position: relative;
  /* flex, а не inline-flex: у строчного элемента под ним остаётся зазор
     под выносные элементы шрифта, и остриё не доставало бы до точки. */
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 34px;
  /* Высота хвостика: метка стоит якорем bottom, остриё — ровно на точке. */
  margin-bottom: 7px;
  padding: 0 14px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 800;
  white-space: nowrap;
  box-shadow: 0 10px 28px rgba(13, 15, 18, .22);
}

.project-map-marker--house .project-map-pin::after,
.project-map-marker--office .project-map-pin::after {
  content: "";
  position: absolute;
  top: 100%;
  left: 50%;
  border: 7px solid transparent;
  border-bottom: 0;
  transform: translateX(-50%);
}

.project-map-marker--house .project-map-pin {
  background: #15181d;
  color: #fff;
}

.project-map-marker--house .project-map-pin::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #fdb82a;
}

.project-map-marker--house .project-map-pin::after {
  border-top-color: #15181d;
}

.project-map-marker--office .project-map-pin {
  background: #fdb82a;
  color: #15181d;
}

.project-map-marker--office .project-map-pin::after {
  border-top-color: #fdb82a;
}

/* Подпись под точкой (рантайм: южная из двух точек, дома и отдела продаж,
   чтобы близкие подписи не накрывали друг друга). Якорь — top. */
.project-map-marker--below .project-map-pin {
  margin-top: 7px;
  margin-bottom: 0;
}

.project-map-marker--below .project-map-pin::after {
  top: auto;
  bottom: 100%;
  border: 7px solid transparent;
  border-top: 0;
}

.project-map-marker--house.project-map-marker--below .project-map-pin::after {
  border-bottom-color: #15181d;
}

.project-map-marker--office.project-map-marker--below .project-map-pin::after {
  border-bottom-color: #fdb82a;
}

.project-map-marker--place .project-map-pin {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  padding: 0;
  border: 2px solid #fff;
  border-radius: 50%;
  background: var(--map-color, #15181d);
  color: #fff;
  box-shadow: 0 4px 12px rgba(13, 15, 18, .28);
  cursor: pointer;
  transition: transform .15s ease;
}

.project-map-pin-icon svg {
  display: block;
  width: 16px;
  height: 16px;
}

.project-map-marker--place:hover {
  z-index: 4;
}

.project-map-marker--place:hover .project-map-pin,
.project-map-marker--place.is-open .project-map-pin,
.project-map-marker--place .project-map-pin:focus-visible {
  transform: scale(1.15);
}

.project-map-tip {
  position: absolute;
  bottom: calc(100% + 8px);
  left: 50%;
  display: grid;
  gap: 3px;
  padding: 8px 12px;
  border-radius: 12px;
  background: #fff;
  color: #15181d;
  font-size: 13px;
  font-weight: 700;
  line-height: 1.2;
  white-space: nowrap;
  box-shadow: 0 10px 28px rgba(13, 15, 18, .18);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translate(-50%, 4px);
  transition: opacity .15s ease, transform .15s ease, visibility .15s;
}

.project-map-tip-distance {
  color: rgba(21, 24, 29, .55);
  font-size: 12px;
  font-weight: 600;
}

.project-map-marker--place:hover .project-map-tip,
.project-map-marker--place.is-open .project-map-tip,
.project-map-pin:focus-visible + .project-map-tip {
  opacity: 1;
  visibility: visible;
  transform: translate(-50%, 0);
}

/* --- Список точек: для экранного диктора, а если карта не загрузилась — на виду. --- */

.project-map-points {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: 0;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  list-style: none;
}

.project-map[data-map-state="failed"] .project-map-points {
  z-index: 1;
  top: 68px;
  left: 16px;
  width: min(360px, calc(100% - 32px));
  height: auto;
  max-height: calc(100% - 84px);
  display: grid;
  align-content: start;
  gap: 8px;
  padding: 14px 16px;
  overflow: auto;
  clip-path: none;
  white-space: normal;
  border-radius: 18px;
  background: rgba(255, 255, 255, .95);
  box-shadow: 0 10px 28px rgba(13, 15, 18, .14);
}

.project-map-point {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-size: 14px;
  line-height: 1.3;
}

/* display: flex выше перебил бы атрибут hidden, которым легенда прячет строки. */
.project-map-point[hidden] {
  display: none;
}

.project-map-point[data-kind="house"] {
  font-weight: 800;
}

.project-map-point-distance {
  color: rgba(21, 24, 29, .55);
  white-space: nowrap;
}

.project-map-point-distance:empty {
  display: none;
}

/* --- Поездка в отдел продаж --- */

.location-actions {
  flex-wrap: wrap;
}

/* display: inline-flex у ссылок блока перебивал атрибут hidden: скрытая
   «Панорама 360°» (ведёт на эту же секцию) была видна. */
.location-actions a[hidden] {
  display: none;
}

.location-trip,
.location-trip-links {
  display: contents;
}

.location-office {
  flex: 1 1 100%;
  margin: 0;
  color: rgba(21, 24, 29, .62);
  font-size: 14px;
  text-align: right;
}

.location-office-address:not(:empty)::before {
  content: " · ";
}

.location-actions a.location-trip-taxi {
  border-color: #15181d;
  background: #15181d;
  color: #fff;
}

@media (max-width: 980px) {
  .location-office {
    text-align: left;
  }
}

@media (max-width: 767px) {
  /* Одна строка с прокруткой; край гаснет — видно, что дальше есть ещё. */
  .project-map-legend {
    right: 56px;
    flex-wrap: nowrap;
    overflow-x: auto;
    pointer-events: auto;
    scrollbar-width: none;
    -webkit-mask-image: linear-gradient(to right, #000 85%, transparent);
    mask-image: linear-gradient(to right, #000 85%, transparent);
  }

  .project-map-legend::-webkit-scrollbar {
    display: none;
  }

  /* Тень прокрутка обрезала бы прямоугольником — на телефоне вместо неё рамка. */
  .project-map-filter {
    flex: 0 0 auto;
    border: 1px solid rgba(21, 24, 29, .1);
    box-shadow: none;
  }
}
